/* Higher Bloom-level questions (bloom.js) join each zone's scan questions. */
LEVELED.forEach((qs, i) => ZONES[i].mc.push(...qs));
// Practice midterm questions join their zone (tagged with n so scans can be labeled "Practice midterm").
for (const m of MIDTERM) ZONES[m.zone].mc.push({ ...m, set: 1 });
for (const m of MIDTERM2) ZONES[m.zone].mc.push({ ...m, set: 2 });

EXTRA.forEach((x, i) => {
  const z = ZONES[i];
  z.mc.push(...(x.mc || []));
  z.creature.qs.push(...(x.qs || []));
  z.specials = (z.specials || []).concat(x.specials || []);
});

